const DEMO_BACKEND_USER_ID = "user-demo-01";
const API_URL = (process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001").replace(/\/$/, "");
async function request(path, init) {
    const response = await fetch(`${API_URL}${path}`, {
        ...init,
        headers: {
            "Content-Type": "application/json",
            ...init?.headers
        }
    });
    if (!response.ok) {
        const body = await response.json().catch(()=>null);
        const message = Array.isArray(body?.message) ? body.message.join(", ") : body?.message;
        throw new Error(message || `Request failed (${response.status})`);
    }
    return response.json();
}
function mapOrder(order) {
    return {
        id: order.id,
        userId: order.userId,
        status: order.status,
        total: order.total,
        createdAt: order.createdAt,
        items: order.items.map((item)=>({
                productId: item.productId,
                name: item.name,
                basePrice: item.unitPrice - item.sizePrice - item.toppingsPrice,
                size: {
                    name: item.sizeName ?? "S",
                    price: item.sizePrice
                },
                toppings: item.toppings,
                qty: item.quantity,
                lineTotal: item.lineTotal
            }))
    };
}
const createOrderApi = async (payload)=>{
    const order = await request("/orders", {
        method: "POST",
        body: JSON.stringify({
            userId: payload.userId,
            items: payload.items.map((item)=>({
                    productId: item.productId,
                    name: item.name,
                    qty: item.qty,
                    basePrice: item.basePrice,
                    lineTotal: item.lineTotal,
                    size: item.size,
                    toppings: item.toppings
                })),
            couponCode: payload.couponCode
        })
    });
    return mapOrder(order);
};
const processPaymentApi = async (payload)=>{
    const payment = await request("/payments", {
        method: "POST",
        headers: {
            "Idempotency-Key": payload.idempotencyKey
        },
        body: JSON.stringify({
            orderId: payload.orderId,
            method: payload.method
        })
    });
    return {
        orderId: payment.order.id,
        status: payment.order.status
    };
};
const getMyOrdersApi = async (userId)=>{
    const orders = await request(`/orders/user/${encodeURIComponent(userId)}`);
    return orders.map(mapOrder);
};
const getLoyaltyPointsApi = async (userId)=>{
    const loyalty = await request(`/users/${encodeURIComponent(userId)}/loyalty`);
    return loyalty.loyaltyPoints;
};
